class Solution {
public:
    vector<int> findPattern(vector<vector<int>>& board, vector<string>& pattern) {
        int R = board.size(), C = board[0].size();
        int r = pattern.size(), c = pattern[0].size();
        for (int i = 0; i + r <= R; ++i) for (int j = 0; j + c <= C; ++j) {
            int forward[26], backward[10];
            fill(forward, forward + 26, -1);
            fill(backward, backward + 10, -1);
            bool ok = true;
            for (int x = 0; x < r && ok; ++x) for (int y = 0; y < c; ++y) {
                char ch = pattern[x][y];
                int d = board[i + x][j + y];
                if (isdigit(ch)) { if (ch - '0' != d) ok = false; }
                else {
                    int a = ch - 'a';
                    if ((forward[a] != -1 && forward[a] != d) ||
                        (backward[d] != -1 && backward[d] != a)) ok = false;
                    forward[a] = d; backward[d] = a;
                }
            }
            if (ok) return {i, j};
        }
        return {-1, -1};
    }
};
